/** The street network: nodes at street points (shared at intersections), edges along streets, a grid of edges. */
function network() {
  const nodes = [], idx = new Map(), edges = [];
  const id = (p) => { const k = p[0].toFixed(3) + ',' + p[1].toFixed(3); if (!idx.has(k)) { idx.set(k, nodes.length); nodes.push(p); } return idx.get(k); };
  for (const s of STREETS) for (let i = 0; i < s.length - 1; i++) { const a = id(s[i]), b = id(s[i + 1]); if (a !== b) edges.push([a, b, Math.hypot(s[i + 1][0] - s[i][0], s[i + 1][1] - s[i][1])]); }
  const adj = nodes.map(() => []); edges.forEach(([a, b, w], e) => { adj[a].push([b, w]); adj[b].push([a, w]); });
  const grid = new Map(), cell = (x, y) => `${Math.floor(x)},${Math.floor(y)}`;
  edges.forEach(([a, b], e) => { const A = nodes[a], B = nodes[b]; for (let x = Math.floor(Math.min(A[0], B[0])) - 1; x <= Math.floor(Math.max(A[0], B[0])) + 1; x++) for (let y = Math.floor(Math.min(A[1], B[1])) - 1; y <= Math.floor(Math.max(A[1], B[1])) + 1; y++) { const k = `${x},${y}`; if (!grid.has(k)) grid.set(k, []); grid.get(k).push(e); } });
  /** Nearest point on any street: {e, t, d, a, b, L, q}. */
  const snap = (p) => {
    let best = null; const cand = grid.get(cell(p[0], p[1])) || edges.map((_, e) => e);
    for (const e of cand) { const [a, b, L] = edges[e], A = nodes[a], B = nodes[b], dx = B[0] - A[0], dy = B[1] - A[1];
      let t = ((p[0] - A[0]) * dx + (p[1] - A[1]) * dy) / (L * L || 1e-12); t = Math.max(0, Math.min(1, t));
      const q = [A[0] + t * dx, A[1] + t * dy], d = Math.hypot(p[0] - q[0], p[1] - q[1]); if (!best || d < best.d) best = { e, t, d, a, b, L, q }; }
    return best;
  };
  /** Dijkstra from a snapped source: distances and predecessors. */
  const dijkstra = (s) => {
    const n = nodes.length, dist = new Float64Array(n).fill(Infinity), prev = new Int32Array(n).fill(-1), done = new Uint8Array(n);
    dist[s.a] = s.d + s.t * s.L; dist[s.b] = s.d + (1 - s.t) * s.L;
    for (;;) { let u = -1, bd = Infinity; for (let i = 0; i < n; i++) if (!done[i] && dist[i] < bd) { bd = dist[i]; u = i; } if (u < 0) break; done[u] = 1; for (const [v, w] of adj[u]) if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; prev[v] = u; } }
    return { dist, prev };
  };
  return { nodes, edges, snap, dijkstra };
}
/** Walking distance from pump source (snapped ps, Dijkstra D) to a snapped point s, and the end node used. */
function walkTo(N, ps, D, s) {
  const via = [[D.dist[s.a] + s.t * s.L, s.a], [D.dist[s.b] + (1 - s.t) * s.L, s.b]].sort((x, y) => x[0] - y[0])[0];
  let d = via[0] + s.d, node = via[1]; if (ps.e === s.e) { const dd = ps.d + s.d + Math.abs(ps.t - s.t) * s.L; if (dd < d) { d = dd; node = -1; } }
  return { d, node };
}

